model=\"userGuidance\"\n          class=\"zhino-sg-textarea\"\n          placeholder=\"例如：&#10;• 白娅在湖边的告白很重要&#10;• 主角获得了火焰剑&#10;• 与商人的交易细节不要遗漏&#10;• 洛月对主角态度的微妙变化\"\n          rows=\"6\"\n        />\n        <div class=\"zhino-sg-info\">\n          <span>待总结楼层: {{ pendingFloors }} 层</span>\n          <span>预计耗时: 30-60秒</span>\n        </div>\n      </div>\n      <div class=\"zhino-sg-footer\">\n        <button class=\"zhino-sg-btn secondary\" @click=\"$emit('skip')\">跳过（AI自行判断）</button>\n        <button class=\"zhino-sg-btn primary\" @click=\"onConfirm\">开始总结</button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nconst props = defineProps<{\n  visible: boolean;\n  pendingFloors: number;\n  initialGuidance?: string;\n  isMobile?: boolean;\n}>();\n\nconst emit = defineEmits<{\n  confirm: [guidance: string];\n  skip: [];\n  cancel: [];\n}>();\n\nconst userGuidance = ref('');\nconst textareaRef = ref<HTMLTextAreaElement | null>(null);\n\n// ═══ overlay 填满父窗口：position:fixed + inline px ═══\n// 关键：快照模式——在 visible 变为 true 时获取一次尺寸，之后不再变化\n// 避免键盘弹出后 viewport 变化导致 overlay 延迟缩小、弹窗被裁切\nconst overlaySize = ref({ w: 0, h: 0 });\n\nwatch(() => props.visible, (val) => {\n  if (val) {\n    // 快照当前父窗口尺寸\n    const hw = window.parent ?? window;\n    overlaySize.value = {\n      w: hw.innerWidth,\n      h: hw.innerHeight,\n    };\n    userGuidance.value = props.initialGuidance || '';\n    nextTick(() => textareaRef.value?.focus());\n  }\n});\n\nconst overlayStyle = computed(() => ({\n  left: '0px',\n  top: '0px',\n  width: overlaySize.value.w + 'px',\n  height: overlaySize.value.h + 'px',\n}));\n\nfunction onConfirm() {\n  emit('confirm', userGuidance.value.trim());\n}\n</script>\n\n<style scoped>\n.zhino-sg-overlay {\n  position: fixed;\n  z-index: 10000;\n  background: rgba(0, 0, 0, 0.6);\n  backdrop-filter: blur(4px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 16px;\n}\n/* 手机端：卡片上移 + 缩小，避免键盘遮挡按钮 */\n.zhino-sg-overlay.mobile {\n  align-items: flex-start;\n  padding: 5vh 16px 16px;\n}\n.zhino-sg-card {\n  background: #0a0d14;\n  border: 1px solid rgba(167, 139, 250, 0.2);\n  border-radius: 12px;\n  box-shadow: 0 0 40px rgba(167, 139, 250, 0.1), 0 20px 60px rgba(0, 0, 0, 0.5);\n  width: 100%;\n  max-width: 480px;\n  max-height: 90%;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n}\n.zhino-sg-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 14px 16px;\n  border-bottom: 1px solid rgba(167, 139, 250, 0.12);\n}\n.zhino-sg-title {\n  font-size: 14px;\n  font-weight: 600;\n  color: #a78bfa;\n}\n.zhino-sg-close {\n  width: 24px;\n  height: 24px;\n  border: none;\n  background: transparent;\n  color: rgba(255, 255, 255, 0.4);\n  font-size: 14px;\n  cursor: pointer;\n  border-radius: 4px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.zhino-sg-close:hover {\n  background: rgba(167, 139, 250, 0.15);\n  color: #a78bfa;\n}\n.zhino-sg-body {\n  padding: 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n.zhino-sg-desc {\n  font-size: 13px;\n  color: rgba(255, 255, 255, 0.75);\n  line-height: 1.6;\n  margin: 0;\n}\n.zhino-sg-hint {\n  font-size: 12px;\n  color: rgba(255, 255, 255, 0.4);\n}\n.zhino-sg-textarea {\n  width: 100%;\n  min-height: 120px;\n  padding: 10px 12px;\n  border: 1px solid rgba(167, 139, 250, 0.2);\n  border-radius: 8px;\n  background: rgba(5, 8, 16, 0.8);\n  color: rgba(255, 255, 255, 0.88);\n  font-size: 13px;\n  line-height: 1.5;\n  resize: vertical;\n  font-family: inherit;\n  box-sizing: border-box;\n}\n.zhino-sg-textarea:focus {\n  outline: none;\n  border-color: rgba(167, 139, 250, 0.5);\n  box-shadow: 0 0 0 2px rgba(167, 139, 250, 0.1);\n}\n.zhino-sg-textarea::placeholder {\n  color: rgba(255, 255, 255, 0.25);\n}\n.zhino-sg-info {\n  display: flex;\n  justify-content: space-between;\n  font-size: 11px;\n  color: rgba(255, 255, 255, 0.35);\n}\n.zhino-sg-footer {\n  display: flex;\n  gap: 8px;\n  padding: 12px 16px;\n  border-top: 1px solid rgba(167, 139, 250, 0.12);\n}\n.zhino-sg-btn {\n  flex: 1;\n  padding: 9px 16px;\n  border-radius: 8px;\n  font-size: 13px;\n  font-weight: 500;\n  cursor: pointer;\n  border: 1px solid transparent;\n  transition: all 0.15s;\n}\n.zhino-sg-btn.primary {\n  background: rgba(167, 139, 250, 0.15);\n  border-color: rgba(167, 139, 250, 0.3);\n  color: #a78bfa;\n}\n.zhino-sg-btn.primary:hover {\n  background: rgba(167, 139, 250, 0.25);\n  border-color: rgba(167, 139, 250, 0.5);\n}\n.zhino-sg-btn.secondary {\n  background: transparent;\n  border-color: rgba(255, 255, 255, 0.1);\n  color: rgba(255, 255, 255, 0.5);\n}\n.zhino-sg-btn.secondary:hover {\n  background: rgba(255, 255, 255, 0.05);\n  color: rgba(255, 255, 255, 0.7);\n}\n</style>\n"],"sourceRoot":""}]);
