t-dim);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}.zhino-btn-icon[data-v-c9b940cc]{width:28px;height:28px;border-radius:6px;border:none;background:transparent;color:var(--zn-text-dim);display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;transition:all 0.15s}.zhino-btn-icon[data-v-c9b940cc]:hover{background:var(--zn-primary-dim);color:var(--zn-primary)}.zhino-tab-switch[data-v-c9b940cc]{display:flex;gap:0;flex-shrink:0;border-bottom:1px solid var(--zn-border);background:rgba(5,8,16,0.6)}.zhino-tab-btn[data-v-c9b940cc]{flex:1;padding:7px 0;font-size:12px;font-weight:600;color:var(--zn-text-dim);background:transparent;border:none;border-bottom:2px solid transparent;cursor:pointer;transition:all 0.15s;text-align:center}.zhino-tab-btn[data-v-c9b940cc]:hover{color:var(--zn-text);background:rgba(167,139,250,0.04)}.zhino-tab-btn.active[data-v-c9b940cc]{color:var(--zn-primary);border-bottom-color:var(--zn-primary);background:var(--zn-primary-dim)}.mobile .zhino-tab-btn[data-v-c9b940cc]{padding:10px 0;font-size:13px}.zhino-panel-content[data-v-c9b940cc]{flex:1;min-height:0;overflow:hidden;padding:12px;display:flex;flex-direction:column}.zhino-resize-handle[data-v-c9b940cc]{position:absolute;right:0;bottom:0;width:16px;height:16px;cursor:nwse-resize;z-index:5}.zhino-resize-handle[data-v-c9b940cc]::after{content:'';position:absolute;right:3px;bottom:3px;width:8px;height:8px;border-right:2px solid rgba(167,139,250,0.25);border-bottom:2px solid rgba(167,139,250,0.25)}.zhino-resize-handle[data-v-c9b940cc]:hover::after{border-color:rgba(167,139,250,0.5)}.zhino-swipe-hint[data-v-c9b940cc]{display:flex;justify-content:center;padding:6px 0 2px;cursor:pointer;flex-shrink:0;background:rgba(5,8,16,0.8);touch-action:none}.zhino-swipe-bar[data-v-c9b940cc]{width:36px;height:4px;border-radius:2px;background:rgba(255,255,255,0.2)}.zhino-swipe-hint:active .zhino-swipe-bar[data-v-c9b940cc]{background:rgba(167,139,250,0.5)}.zhino-mobile-close-bar[data-v-c9b940cc]{flex-shrink:0;padding:8px 12px;padding-bottom:max(12px,env(safe-area-inset-bottom,12px));border-top:1px solid var(--zn-border);background:rgba(5,8,16,0.9);display:flex;justify-content:center}.zhino-mobile-close-btn[data-v-c9b940cc]{display:inline-flex;align-items:center;gap:6px;padding:8px 24px;border-radius:8px;border:1px solid rgba(167,139,250,0.2);background:rgba(167,139,250,0.06);color:var(--zn-primary);font-size:13px;font-weight:500;cursor:pointer;width:100%;justify-content:center}.zhino-mobile-close-btn[data-v-c9b940cc]:hover,.zhino-mobile-close-btn[data-v-c9b940cc]:active{background:rgba(167,139,250,0.15);border-color:rgba(167,139,250,0.4)}.zhino-fab-enter-active[data-v-c9b940cc],.zhino-fab-leave-active[data-v-c9b940cc]{transition:opacity 0.2s ease}.zhino-fab-enter-from[data-v-c9b940cc],.zhino-fab-leave-to[data-v-c9b940cc]{opacity:0}.zhino-panel-enter-active[data-v-c9b940cc],.zhino-panel-leave-active[data-v-c9b940cc]{transition:all 0.25s ease}.zhino-panel-enter-from[data-v-c9b940cc]{opacity:0}.zhino-panel-leave-to[data-v-c9b940cc]{opacity:0}.mobile.zhino-panel-enter-from[data-v-c9b940cc]{opacity:0}.mobile.zhino-panel-leave-to[data-v-c9b940cc]{opacity:0}
